// Generates the dashboard's view of the Management API from the published contract,
// `contract/management-api.yaml` — the only artefact the dashboard shares with the server.
//
//   src/contract/management-api.ts  the request and response types (openapi-typescript)
//   src/contract/scopes.ts           the scopes the contract defines, with their descriptions
//
// Run `npm run contract` after replacing the contract with a newer release of it; the
// generated files are committed, so a build never depends on the network or the server.

import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";
import { parse } from "yaml";

const root = new URL("../", import.meta.url);
const source = new URL("contract/management-api.yaml", root);
const banner = "// Generated by `npm run contract` from contract/management-api.yaml. Do not edit.\n\n";

const document = parse(await readFile(source, "utf8"));

const types = astToString(await openapiTS(document, { alphabetize: false, exportType: true }));
await writeFile(new URL("src/contract/management-api.ts", root), banner + types);

const flows = document.components?.securitySchemes?.managementToken?.flows ?? {};
const scopes = Object.values(flows).reduce((all, flow) => ({ ...all, ...(flow.scopes ?? {}) }), {});
if (Object.keys(scopes).length === 0) {
  throw new Error("The contract defines no scope for managementToken.");
}
const entries = Object.entries(scopes)
  .map(([scope, description]) => `  ${JSON.stringify(scope)}: ${JSON.stringify(description)},`)
  .join("\n");
await writeFile(
  new URL("src/contract/scopes.ts", root),
  banner +
    "/** Every scope the Management API defines, with what it allows. */\n" +
    `export const MANAGEMENT_SCOPES = {\n${entries}\n} as const;\n\n` +
    "export type ManagementScope = keyof typeof MANAGEMENT_SCOPES;\n",
);

console.log(`Generated the contract types and ${Object.keys(scopes).length} scopes from ${fileURLToPath(source)}`);
